-- Venue Live Guest "Papan Perpisahan". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara farewell), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'farewell', 'Papan Perpisahan', 'farewell', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 155, 'center 38%',
  $t${"name":"Papan Perpisahan","orn":"diamond","ui":{"ivory":"#F8F4FF","white":"#FFFFFF","soft":"#E6DAF8","soft2":"#B79BE3","accent":"#7E57C2","deep":"#3E2A6B","ink":"#3E2A6B","mute":"#8C7CAF","line":"#E1D6F3","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#FBF8FF","ink":"#3E2A6B","accent":"#7E57C2","gold":"#C9A24A","leaf":"#E6DAF8","hbg":"rgba(248,244,255,.94)","hline":"#C9A24A","motif":"diamond"},"hud":{"bg":"rgba(62,42,107,.9)","acc":"#F2D27A","on":"#3E2A6B"},"scr":{"wine":"#3E2A6B","veil":"248,244,255"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'farewell');
